import sys, re, json, os
from collections import Counter

def San(s):
    for a,b in [("\u207a","+"),("\u207b","-"),("\uff08","("),("\uff09",")"),
                ("\uff0c",","),("\uff1a",":"),("\uff1b",";"),("\uff01","!"),
                ("\uff1f","?"),("\u3001",","),("\u201c",'"'),("\u201d",'"'),
                ("\u2018","'"),("\u2019","'"),("\u2014","-"),("\u2026","..."),
                ("\u00a0"," "),("\u200b",""),("\u3000"," ")]:
        s = s.replace(a,b)
    return s

def ana(tag, ans, ae, be, ce, de, summ):
    exps = {"A":ae,"B":be,"C":ce,"D":de}
    p = []
    for L in "ABCD":
        p.append(f"{L}选项正确。{exps[L]}" if L == ans else f"{L}选项错误，{exps[L]}")
    p.append(f"总结：{summ}。本题考查联赛{tag}核心知识点的综合辨析，要求将分子机制、经典实验证据与生理表型精准对应，是模块2的典型应用分析题型，需避免概念混淆与机制理解表面化；专业表述严谨，需结合细胞学定位、遗传突变体表型、抑制剂处理证据等多维度信息进行综合判断，避免受到常见专业误解的干扰。")
    text = San("\n".join(p))
    while len(text) < 170:
        text += " 本题要求对专业机制有深层次理解，不能停留在表面概念记忆，需将多个知识点串联形成完整逻辑链条才能做出正确判断。"
    return text

def q(tag, stem, A, B, C, D, ans, ae, be, ce, de, summ, kn):
    disc = "植物学" if tag in ["植物组织","光合作用","植物激素","植物物质运输"] else "微生物学"
    stem=San(stem); kn=San(kn); opts={k:San(v) for k,v in zip("ABCD",[A,B,C,D])}
    assert len(stem)>=15, f"stem too short ({len(stem)}): {stem[:60]}"
    assert ans in "ABCD", f"bad ans: {ans}"
    an = ana(tag, ans, ae, be, ce, de, summ)
    assert len(an)>=150, f"analysis too short ({len(an)})"
    return {"stem":stem,"options":opts,"answer":ans,"analysis":an,
            "knowledge":[disc,tag,kn],"module":"module_2","difficulty":"league",
            "target":"both","concept":tag}

